def link(url,txt,cls='text-link'):return f'<a class="{cls}" href="{E(url)}">{txt} {ARROW}</a>'
def photo(n,cls='',eager=False,caption=None):
 a=next(photo for photo in M if photo["id"]==n);o=f'<figure class="photo {cls}"><img src="assets/photos/{n:02}.webp" srcset="assets/photos/{n:02}-sm.webp {round(a["width"]*min(1,640/max(a["width"],a["height"])))}w, assets/photos/{n:02}.webp {a["width"]}w" sizes="(max-width: 700px) 92vw, 48vw" width="{a["width"]}" height="{a["height"]}" alt="{E(a["alt"])}" loading="{"eager" if eager else "lazy"}" decoding="async"'+(' fetchpriority="high"' if eager else '')+'>'
 return o+(f'<figcaption>{caption}</figcaption>' if caption else '')+'</figure>'
def button(url,txt,secondary=False):return link(url,txt,'button'+(' secondary' if secondary else ''))
def eyebrow(s):return f'<p class="eyebrow">{s}</p>'
def intro(k,title,desc=''):return f'<header class="page-heading wrap">{eyebrow(k)}<h1>{title}</h1>'+ (f'<p class="lede">{desc}</p>' if desc else '')+'</header>'
