def teaser():return f'''<aside class="class-teaser wrap reveal"><div class="date-lockup"><strong>03</strong><span>December<br/>2026</span></div><div>{eyebrow('Offline classes in Mysuru')}<h2>{SIGN}</h2><p>Offline Bharatanatyam classes begin at Jayanagara Rama Mandira.</p><p class="online-teaser">Online classes: <a href="{WA}">contact Krithi on WhatsApp {ARROW}</a></p></div>{interest_link('offline')}</aside>'''
def profile_download():
 cards = ''.join(
  f'<a class="profile-card" href="/assets/profiles/Krithi-Kailar-{language}.pdf" download="Krithi-Kailar-{language}.pdf" hreflang="{code}" aria-label="Download {language} profile PDF"><strong>{label}</strong><small>{detail}</small></a>'
  for language, code, label, detail in [('English', 'en', 'English', 'PDF'), ('Kannada', 'kn', '<span lang="kn">ಕನ್ನಡ</span>', 'Kannada PDF')]
 )
 return f'''<details class="profile-download"><summary><svg aria-hidden="true" width="18" height="18" viewBox="0 0 24 24" fill="currentColor"><path d="M11 3h2v10l3.5-3.5 1.4 1.4L12 17l-5.9-6.1 1.4-1.4L11 13zM5 18h14v3H5z"/></svg>Download profile</summary><div class="profile-panel">{cards}</div></details>'''
def header(current):
 nav=''.join(f'<a href="{u}"'+(' aria-current="page"' if current==u else '')+f'>{t}</a>' for u,t in NAV)
 mobile=''.join(f'<a href="{u}"'+(' aria-current="page"' if current==u else '')+f'><small>{i+1:02}</small>{t}</a>' for i,(u,t) in enumerate(PAGES))
 return f'''<a class="skip" href="#main">Skip to content</a><div class="announcement"><span class="live-dot" aria-hidden="true"></span><span>{SCHOOL} · Offline classes from <strong>3 December</strong></span><a href="classes.html">Enquire {ARROW}</a></div><header class="site-header"><a href="index.html" class="brand" aria-label="Krithi Kailar, home"><img class="brand-monogram ink-logo" src="assets/brand/kk-monogram.png" width="45" height="45" alt=""><span class="brand-title"><img class="ink-logo" src="assets/brand/krithi-kailar-wordmark.png" width="135" height="90" alt="Krithi Kailar"><small>BHARATANATYAM</small></span></a><nav class="desktop-nav" aria-label="Main navigation">{nav}</nav><div class="header-actions">{profile_download()}<a href="classes.html" class="nav-cta">Learn with Krithi {ARROW}</a><button class="menu-toggle" aria-label="Open menu" aria-haspopup="dialog"><span></span><span></span></button></div></header><dialog id="mobile-menu" aria-label="Explore all pages"><div class="menu-top"><span class="eyebrow">Explore the world of Krithi Kailar</span><button class="menu-close icon-button" aria-label="Close menu">×</button></div><nav aria-label="All pages">{mobile}</nav><a class="menu-phone" href="{WA}">WhatsApp +91 84315 34682</a></dialog>'''
def footer():
 return f'''<footer class="site-footer wrap"><div class="footer-top"><a href="index.html" class="footer-name" aria-label="Krithi Kailar, home"><img class="ink-logo" src="assets/brand/krithi-kailar-wordmark.png" width="230" height="153" alt="Krithi Kailar"></a><p>Dance. Reflection. Belonging.<br/><span>Bharatanatyam, rooted in Mysuru.</span></p>{link('contact.html','Begin a conversation')}</div><div class="footer-nav">{''.join(f'<a href="{u}">{t}</a>' for u,t in PAGES[1:])}</div><div class="footer-bottom"><span>© {datetime.date.today().year} Krithi Kailar</span><span><a href="{WA}">WhatsApp +91 84315 34682</a> <i> / </i> <a href="{INST}" target="_blank" rel="noopener noreferrer">Instagram ↗</a></span><span>Pratyavēkṣiṇī</span></div></footer>'''
def write(file,title,desc,body,cls=''):
 schema={'@context':'https://schema.org','@type':'Person','name':'Krithi Kailar','honorificPrefix':'Vidushi','url':'https://krithikailar.in/','jobTitle':'Bharatanatyam artiste and teacher','sameAs':[INST],'telephone':'+918431534682','email':'kailarkrithi@gmail.com'}
 txt=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | Vidushi Krithi Kailar</title><meta name="description" content="{E(desc)}"><meta name="theme-color" content="#1b1412"><link rel="canonical" href="https://krithikailar.in/{'' if file=='index.html' else file}"><meta property="og:type" content="website"><meta property="og:title" content="{E(title)} | Krithi Kailar"><meta property="og:description" content="{E(desc)}"><meta property="og:url" content="https://krithikailar.in/{'' if file=='index.html' else file}"><meta property="og:image" content="https://krithikailar.in/assets/photos/performance-stage.webp"><meta name="twitter:card" content="summary_large_image"><link rel="icon" type="image/png" href="assets/brand/kk-monogram.png"><link rel="apple-touch-icon" href="assets/brand/kk-monogram.png"><link rel="preload" href="assets/fonts/BVNanda-Regular.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="assets/fonts/fonts.css"><link rel="stylesheet" href="assets/site.css"><script type="application/ld+json">{json.dumps(schema)}</script><script defer src="assets/site.js"></script></head><body class="{cls}">{header(file)}<main id="main">{body}</main>{interest_form}{footer()}</body></html>'''
 assert '\u2014' not in txt
 (R/file).write_text(txt)

home=f'''<section class="hero hero-stage"><figure class="hero-stage-image"><picture><source media="(max-width: 700px)" srcset="assets/photos/22.webp"><img src="assets/photos/performance-stage.webp" width="1774" height="887" alt="Krithi Kailar smiling during a Bharatanatyam performance, with one arm raised, against a blue-lit stage" fetchpriority="high" loading="eager"></picture></figure><div class="hero-copy">{eyebrow('Vidushi | Artiste · Choreographer · Teacher')}<h1 class="hero-wordmark"><span class="sr-only">Vidushi Krithi Kailar</span><img class="ink-logo" src="assets/brand/krithi-kailar-wordmark.png" width="1536" height="1024" alt=""></h1><p class="hero-poem">The body speaks.<br/>The spirit listens.</p><div class="hero-links">{link('about.html','Meet the artiste')}{link('performances.html','Enter the stage')}</div><a class="hero-class" href="classes.html"><span>OFFLINE CLASSES · MYSURU</span>{SIGN}<small>From 3 December 2026 · Jayanagara Rama Mandira {ARROW}</small></a>{interest_link('offline')}<a class="hero-online" href="classes.html?mode=online#class-interest">Online classes · I am interested {ARROW}</a></div><a class="hero-side" href="pratyaveksini.html">PRATYAVĒKṢIṆĪ <span>THE REFLECTIVE GAZE</span></a><div class="hero-baseline"><span>Rooted in tradition. Alive in the present.</span><span>Mysuru, Karnataka</span></div></section>{teaser()}<section class="intro-statement wrap reveal">{eyebrow('A life in Bharatanatyam')}<h2>Where disciplined movement<br/>becomes <em>inner experience.</em></h2><p>Sixteen years and more of learning, a continuing dialogue with music and philosophy, and an art offered with attention.</p></section><section class="editorial-links wrap">{''.join(f'<a class="editorial-link reveal" href="{u}">{photo(n)}<span class="eyebrow">{k}</span><h3>{t} {ARROW}</h3></a>' for n,u,k,t in [(5,'pratyaveksini.html','01 / The thought','A reflective gaze'),(71,'productions.html','02 / The telling','Stories in movement'),(35,'journey.html','03 / The practice','A living lineage')])}</section>'''
write('index.html','Bharatanatyam artiste & teacher in Mysuru','Vidushi Krithi Kailar. Explore Bharatanatyam, performances and Pratyavēkṣiṇī. Offline classes begin 3 December 2026 at Jayanagara Rama Mandira, Mysuru.',home,'home')

about=intro('01 / The artiste','A life shaped<br/>by <em>dance.</em>','Vidushi Krithi Kailar | Bharatanatyam artiste, choreographer and teacher.')+f'''<section class="split wrap about-split"><div class="reveal">{photo(4,'portrait tall',True)}<p class="caption">Uppinangady roots. Mysuru practice.</p></div><div class="prose reveal"><h2>Rooted in tradition.<br/><em>Alive in performance.</em></h2><p>From Uppinangady in Dakshina Kannada, Krithi Kailar brings more than sixteen years of training to her Bharatanatyam practice. Her learning draws on the Pandanallur and Kalakshetra bānis within the Guru-Śiṣya Paramparā.</p><p>A Doordarshan B-Grade artiste, she has passed the Post-Vidwath examination with <strong>90% marks, earning distinction</strong>. She is currently pursuing an M.A. in Bharatanatyam at Karnataka State Dr. Gangubai Hangal Music and Performing Arts University.</p><p>Her study of Karnataka Śāstrīya Saṅgīta deepens the relationship between movement, rāga, tāla and sāhitya. The Nāṭyaśāstra and Advaita Vedānta inform her understanding of dance as Darśana Kalā.</p><p>She is the founder of <strong>Akashabharati</strong>, through which she teaches students across the country.</p>{link('journey.html','Follow her journey')}</div></section><section class="credentials wrap reveal"><div><strong>16+</strong><span>years of training</span></div><div><strong>90<span>%</span></strong><span>Post-Vidwath distinction</span></div><div><strong>B-Grade</strong><span>Doordarshan artiste</span></div></section><section class="split wrap section-space"><div class="prose reveal">{eyebrow('Practice & inquiry')}<h2>Śāstra<br/><em>& Prayoga.</em></h2><p>Alongside dance, Krithi completed her BBA LL.B. (Hons.) at JSS Law College, Mysuru in 2026, securing fifth rank. Her interests meet at the intersection of law, saṃskṛti and the traditional arts.</p><p>Her inquiry encompasses abhinaya, Rasa and Dhvani, temple traditions, the Guru-Śiṣya Paramparā and Advaita Vedānta.</p>{link('pratyaveksini.html','The thought behind the art')}</div><div class="paired-photos reveal">{photo(63,'portrait')}{photo(44,'portrait')}</div></section>{teaser()}'''
write('about.html','The artiste','Meet Vidushi Krithi Kailar: Bharatanatyam artiste, Doordarshan B-Grade artiste and founder of Akashabharati, Mysuru.',about)

philosophy=intro('02 / The inner landscape','Pratyavēkṣiṇī','A reflective gaze. A conversation between poetry, sculpture and dance.')+f'''<section class="philosophy-hero wrap">{photo(5,'temple-photo',True)}<div class="philosophy-word"><span lang="kn">ಪ್ರತ್ಯವೇಕ್ಷಿಣಿ</span><p>To look closely.<br/><em>To turn inward.</em></p></div></section><section class="split wrap section-space"><div class="reveal">{eyebrow('The literary connection')}<h2>From D. V. Gundappa’s<br/><em>Antaḥpura Gīte.</em></h2></div><div class="prose reveal"><p>Pratyavēkṣiṇī appears in the opening stanza of <em>Nṛttahāsinī</em> (<span lang="kn">ನೃತ್ತಹಾಸಿನಿ</span>), a poem in D. V. Gundappa’s <em>Antaḥpura Gīte</em>. The collection draws its poetic world from the madanikā sculptures of Belur’s Chennakeshava temple.</p><p>In that meeting of stone, song and imagination, a sculpted gesture becomes an inner life. It offers a fitting point of departure for a dancer: to observe with care, to reflect, and to let form become experience.</p><p>The Sanskrit verbal root <em>praty-ava-īkṣ</em> carries the senses of looking closely, examining and considering. Here, “she who observes and reflects” is the artistic reading of Pratyavēkṣiṇī.</p><p class="source-note">Further reading: <a href="https://musicacademymadras.in/catalogue/files/journals/Vol.46_1975.pdf" target="_blank" rel="noopener noreferrer">B. V. K. Sastri on <em>Antahpura Geete</em>, The Music Academy Journal, 1975</a>; <a href="https://www.wisdomlib.org/definition/pratyaveksh" target="_blank" rel="noopener noreferrer">Sanskrit dictionary entry</a>.</p></div></section><section class="poem-section wrap"><div class="poem-intro reveal">{eyebrow('The poem behind the name')}<h2>Nṛttahāsinī.<br/><em>Poetry in the dancing form.</em></h2><p class="lede">D. V. Gundappa<br/><em>Antaḥpura Gīte</em></p><p>The opening stanza addresses the dancing figure as Pratyavēkṣiṇī. The name carries that poetic connection into Krithi’s practice: a gaze attentive to form, feeling and the life within.</p><a class="text-link" href="assets/literature/nrittahasini-poem.png" target="_blank" rel="noopener">Read the original Kannada page {ARROW}</a></div><figure class="poem-facsimile reveal"><img src="assets/literature/nrittahasini-poem.png" width="408" height="372" alt="Original Kannada page of Nrittahasini from D. V. Gundappa’s Antahpura Gite, with Pratyavekshini in the opening stanza"><figcaption>Nṛttahāsinī · D. V. Gundappa · Antaḥpura Gīte</figcaption></figure></section><section class="philosophy-triptych wrap">{''.join(f'<article class="reveal"><span class="eyebrow">{n}</span><h3>{title}</h3><p>{body}</p></article>' for n,title,body in [('01','Darśana','Dance as a way of seeing. Attention gives a gesture its depth and makes space for meaning.'),('02','Sādhanā','Practice as a continuing discipline. Repetition sharpens the form while reflection opens the experience.'),('03','Bhāva','Feeling made perceptible. The body, music and gaze meet in the telling of a story.')])}</section><section class="quiet-panel wrap reveal">{photo(3)}<div><p class="eyebrow">Krithi’s artistic inquiry</p><h2>The movement outside.<br/><em>The stillness within.</em></h2>{link('performances.html','Experience the performances')}</div></section>'''
write('pratyaveksini.html','Pratyavēkṣiṇī','The thought behind Krithi Kailar’s art: Pratyavēkṣiṇī, D. V. Gundappa’s Antaḥpura Gīte, reflection and Bharatanatyam.',philosophy)

masters=['Padma Bhushan Guru Swapnasundari','Smt. Rama Vaidyanathan','Śrī Vaibhav Arekar','Viduṣī SaiKripa','Śrī Shijith Nambiar','Smt. Parvathy Menon','Viduṣī Meera Sreenarayanan','Viduṣī Divya Ravi','Smt. Kapila Venu','Śrī Manjunath N. Puttur']
journey=intro('03 / The journey','Learning is<br/><em>a lifelong rhythm.</em>','Gurus, practice, scholarship and the milestones along the way.')+f'''<section class="lineage wrap"><div class="lineage-image reveal">{photo(37,'portrait',True)}{photo(6)}</div><div>{eyebrow('Guru-Śiṣya Paramparā')}<ol class="lineage-list"><li class="reveal"><span>01 / Pandanallur</span><h2>Guru Śrī Balakrishna Manjeshwara</h2><p>Twelve years of foundational dance training, beginning at age six.</p></li><li class="reveal"><span>02 / Kalakshetra</span><h2>Viduṣī Smt. Suhasini Koulagi</h2><p>Four years of advanced dance training in Mysuru.</p></li><li class="reveal"><span>03 / Karnataka Śāstrīya Saṅgīta</span><h2>Vidvān Dr. R. S. Nandakumar</h2><p>Rāga, tāla, sāhitya and music for dance. Putra-śiṣya of Mahāmahopādhyāya Dr. R. Sathyanarayana.</p></li></ol></div></section><section class="split wrap section-space"><div class="reveal">{eyebrow('Workshops & masterclasses')}<h2>Practice.<br/>Observe.<br/><em>Refine.</em></h2>{photo(35,'workshop-photo')}</div><ul class="name-list reveal">{''.join(f'<li><span>{i+1:02}</span>{n}</li>' for i,n in enumerate(masters))}</ul></section><section class="honours section-space"><div class="wrap"><div class="section-title reveal">{eyebrow('Recognition')}<h2>Discipline <em>& distinction.</em></h2></div><div class="honour-grid"><article><strong>90%</strong><h3>Post-Vidwath</h3><p>Passed with distinction. Junior, Senior and Pre-Vidwath examinations also cleared with distinction.</p></article><article><strong>B-Grade</strong><h3>Doordarshan</h3><p>Bharatanatyam artiste, Doordarshan Kendra, Bengaluru.</p></article><article><strong>2024–25</strong><h3>Academy scholarship</h3><p>Karnataka Saṅgīta Nṛtya Academy.</p></article></div><div class="award-list">{''.join(f'<div class="reveal"><span>{y}</span><p>{s}</p></div>' for y,s in [('2023 to 2026','Various prizes, Solo Classical Dance Competition, Suttur Jathra Mahotsava.'),('2025','First Prize, Solo Bharatanatyam, Vidyuth, Vidyavardhaka College of Engineering, Mysuru.'),('2024','Jury recognition for the interdisciplinary production Manas, Art Salad Global Art Competition.'),('2024','Special Mention, 47th International Bharatanatyam Competition, Niranthara Kalemane.'),('2024','Top Five Finalist, Rasovaisaha National Dance Festival, Udupi.')])}</div></div></section><section class="wrap section-space"><div class="section-title">{eyebrow('Education')}<h2>Art. Scholarship. <em>Law.</em></h2></div><div class="education-list"><article><span>Present</span><h3>M.A. Bharatanatyam</h3><p>Karnataka State Dr. Gangubai Hangal Music and Performing Arts University.</p></article><article><span>2026</span><h3>BBA LL.B. (Hons.)</h3><p>JSS Law College, Mysuru. Fifth rank in law.</p></article><article><span>2021 / 2019</span><h3>Foundations</h3><p>PCMB at Indraprastha PU College, Uppinangady; SSLC at Indraprastha Vidyalaya, Uppinangady.</p></article></div></section>'''
write('journey.html','Training & recognition','Krithi Kailar’s gurus, training, workshops, education and honours, including Post-Vidwath distinction with 90%.',journey)

venues=['Jaganmohan Palace, Mysore Dasara festivities (2026)','Rajangana stage, Śrī Kṛṣṇa Mutt, Udupi','Guruvayur Temple, Kerala','Suttur Jathra Mahotsava','Puttur Dasara','Śrī Lakṣmī Narasiṃha Svāmī Temple, K. Belathur (Nṛtya Sevā)','Melukote','Mahākālī Mecchi Nemotsava, Uppinangady','Abhivyakti Habba (2022 to 2025)','Kisan Swaraj Sammelana (2022 and 2025)','Save Soil Campaign, Isha Foundation','Veene Sheshanna Bhavana, Ganabharati, Mysuru']
perf=intro('04 / On stage','The stage<br/>as <em>offering.</em>','Solo recitals, complete mārgams and stories told through movement.')+f'''<section class="performance-notice wrap" id="rama-govinda"><div>{eyebrow('Bharatanatyam performance')}<time datetime="2026-11-22">Sunday, 22 November 2026</time><h2>Rama Govinda Ranga Mandira</h2><p>Vidushi Krithi Kailar · Mysuru</p></div><div><address>Nrupatunga Kannada School, Nirvikalpa Road<br/>E &amp; F Block, Ramakrishna Nagar, Mysuru</address>{button(PERFORMANCE_MAP,'View performance venue on Google Maps',True)}</div></section><div class="wide-stage wrap reveal">{photo(17,'',True)}</div><section class="split wrap section-space"><div class="reveal">{eyebrow('Across Karnataka & Kerala')}<h2>Two complete mārgams.<br/><em>Many moments of meeting.</em></h2><p class="lede">A selection of stages and festivals from Krithi’s performance journey.</p>{photo(23,'stage-inset')}</div><ul class="venue-list reveal">{''.join(f'<li>{x}</li>' for x in venues)}</ul></section><section class="wrap section-space"><div class="section-title reveal">{eyebrow('Performance films')}<h2>In motion. <em>In the moment.</em></h2></div><div class="film-grid"><a class="film reveal" href="https://youtu.be/T8qw_6CepYc" target="_blank" rel="noopener noreferrer">{photo(82)}<span class="play" aria-hidden="true">▶</span><div><h3>Manas</h3><p>A creative presentation by Krithi Kailar. Watch on YouTube ↗</p></div></a><a class="film reveal" href="https://youtu.be/sqsqusRni_E" target="_blank" rel="noopener noreferrer">{photo(26)}<span class="play" aria-hidden="true">▶</span><div><h3>Suttur Jathra Mahotsava</h3><p>A performance highlight. Watch on YouTube ↗</p></div></a></div></section><section class="wrap repertoire"><div>{eyebrow('Repertoire')}<h2>Nṛtta. Nṛtya.<br/><em>Abhinaya.</em></h2></div><p>Alarippu · Jātisvaram · Śabdam · Varṇam · Padam · Javali · Kīrtanam · Aṣṭapadi · Devaranāma · Tillānā · Maṅgalam · Śloka-based presentations</p></section>{teaser()}'''
write('performances.html','Performances & repertoire','Explore Krithi Kailar’s Bharatanatyam performances, repertoire, festival appearances and films.',perf)

prod=intro('05 / Productions','Stories in<br/><em>movement.</em>','Choreography, performance and ensemble music.')+f'''<article class="production-feature wrap"><div class="production-copy reveal">{eyebrow('Chintana Ramayana')}<h2>An epic<br/><em>embodied.</em></h2><p>Featured performer and choreographer.</p><p>Nadabrahma Sangeetha Sabha, Mysuru.</p>{link('contact.html','Enquire about performances')}</div>{photo(71,'rama-photo',True)}</article><div class="production-strip wrap">{photo(70)}{photo(74)}{photo(77)}</div><article class="split wrap section-space"><div class="reveal">{photo(79)}{photo(78,'detail-photo')}</div><div class="prose reveal">{eyebrow('Vishwakutumbi')}<h2>Poetry becomes<br/><em>presence.</em></h2><p>Choreographed and performed by Krithi Kailar, based on the kavanas of Pu. Ti. Narasimhachar.</p><p>A meeting of poetic thought, expressive movement and the language of Bharatanatyam.</p></div></article><section class="music-ensemble wrap section-space"><div class="ensemble-photos">{photo(80)}{photo(81)}</div><div class="ensemble-text"><article><h3>RaSa Ghoshti Gayana</h3><p>An ensemble music presentation on the Mysore Palace stage.</p></article><article><h3>Sapthapuri</h3><p>Kṣetra Darśana through Saṅgīta. A seven-member thematic musical presentation under the guidance of her saṅgīta Guru.</p></article></div></section>'''
write('productions.html','Productions','Chintana Ramayana, Vishwakutumbi and ensemble music: productions featuring Krithi Kailar as performer and choreographer.',prod)

classes=f'''<section class="classes-hero wrap"><div class="reveal">{eyebrow('Offline Bharatanatyam classes in Mysuru')}<h1>{SIGN}</h1><p class="lede">Learn Bharatanatyam with<br/>Vidushi Krithi Kailar.</p><div class="class-date"><strong>03</strong><div>December <span>2026 onwards</span></div></div><p class="class-place">Jayanagara Rama Mandira<br/><span>Mysuru</span></p><div class="button-row">{interest_link('offline')}{button(MAP,'Get directions',True)}</div><p class="micro">For batch timings, fees and enrolment, message +91 84315 34682 on WhatsApp.</p></div>{photo(35,'classes-photo',True)}</section><section class="online-classes wrap reveal" id="online"><div>{eyebrow('Learn from wherever you are')}<h2>Online classes.<br/><em>A continuing practice.</em></h2></div><div><p class="lede">Contact Vidushi Krithi Kailar for online Bharatanatyam classes.</p><p>Message Krithi to discuss your experience, availability and class details.</p><div class="button-row">{interest_link('online')}{link('mailto:kailarkrithi@gmail.com','Send an email')}</div></div></section><section class="teaching-note wrap reveal"><div>{eyebrow('A living tradition')}<h2>Attention.<br/>Discipline.<br/><em>Expression.</em></h2></div><div class="prose"><p>Akashabharati is the academy founded by Krithi Kailar, through which she teaches students across the country. She teaches in person at {SCHOOL} in Jayanagara, Mysuru.</p><p>Krithi’s own training spans the Pandanallur and Kalakshetra bānis. Her study of music and the Nāṭyaśāstra informs the relationship between rhythm, movement and meaning.</p>{link('journey.html','Meet her teachers and lineage')}</div></section><section class="location-section wrap" id="location"><div class="location-card reveal">{eyebrow('Come to class')}<h2>Jayanagara<br/><em>Rama Mandira.</em></h2><address>Sri Rama Mandira<br/>2nd Main Road, 16th Cross<br/>Jayanagara, Mysuru<br/>Karnataka 570014</address><div class="button-row">{button(MAP,'Open Google Maps')}{link(WA,'WhatsApp 84315 34682')}</div><p class="source-note"><a href="https://starofmysore.com/sri-ramotsava-at-jayanagar/" target="_blank" rel="noopener noreferrer">Venue address reference ↗</a></p></div><div class="qr-card reveal"><a href="{E(MAP)}" aria-label="Open Jayanagara Rama Mandira location in Google Maps"><img src="assets/brand/location-qr.png" width="248" height="248" alt="QR code linking to Jayanagara Rama Mandira on Google Maps"></a><h3>Find your way.</h3><p>Scan for the class location.<br/>On your phone? Tap the QR code.</p><a href="assets/brand/location-qr.png" download="Krithi-Kailar-class-location.png" class="text-link">Save the location QR ↓</a></div></section><section class="wrap faq section-space"><h2>A few practical <em>details.</em></h2><details><summary>How can I enquire about online classes?</summary><p>Message Krithi directly on <a href="{WA}">WhatsApp at 8431534682</a> or email <a href="mailto:kailarkrithi@gmail.com">kailarkrithi@gmail.com</a> for online Bharatanatyam classes.</p></details><details><summary>When do offline classes begin?</summary><p>Classes begin from 3 December 2026 onwards. Please contact Krithi for the available batch timings.</p></details><details><summary>How do I join?</summary><p>Message <a href="{WA}">8431534682 on WhatsApp</a> or send an Instagram message to <a href="{INST}">@krithikailar</a> to discuss enrolment, fees and the appropriate batch.</p></details><details><summary>Can I enquire as a beginner or a continuing student?</summary><p>Yes. Share your age and previous dance experience, if any, so Krithi can advise you about the class.</p></details></section>'''
